css:
.sl-article-chapters {
    background-color: var(--smartlearn-bg);
    padding-block: 3rem;
    scroll-behavior: smooth;
}
@media (min-width: 992px) {
    .sl-article-chapters { padding-block: 6rem; }
}

.sl-article-chapters .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-article-chapters .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-article-chapters .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-article-chapters .sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-article-chapters .sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-article-chapters .sl-badge-soft {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, transparent);
}
.sl-article-chapters .sl-border { border-color: var(--smartlearn-card-border) !important; }
.sl-article-chapters .sl-tracking-wide { letter-spacing: 0.1em; }

.sl-article-chapters .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}

/* Sticky TOC below fixed navbar */
.sl-article-chapters .sl-toc-sticky {
    position: sticky;
    top: calc(var(--smartlearn-navbar-height, 64px) + 1rem);
    z-index: 10;
}

.sl-article-chapters .sl-chapter {
    scroll-margin-top: calc(var(--smartlearn-navbar-height, 64px) + 1.5rem);
}
.sl-article-chapters .sl-chapter:focus-visible {
    outline: 2px dashed var(--smartlearn-primary);
    outline-offset: 10px;
}

/* Mobile TOC Collapse */
.sl-article-chapters .sl-mobile-toc-collapse { display: none; }
.sl-article-chapters .sl-mobile-toc-collapse.show { display: block; }
.sl-article-chapters .sl-toc-chevron { transition: transform 0.2s ease; }
.sl-article-chapters .sl-mobile-toc-toggle[aria-expanded="true"] .sl-toc-chevron { transform: rotate(180deg); }

/* Logical TOC link borders (RTL-safe) */
.sl-article-chapters .sl-toc-link {
    transition: color 0.2s ease;
    border-inline-start: 2px solid transparent;
    margin-inline-start: -2px;
}
.sl-article-chapters .sl-toc-link:hover,
.sl-article-chapters .sl-toc-link:focus-visible {
    color: var(--smartlearn-text) !important;
}
.sl-article-chapters .sl-toc-link.active {
    color: var(--smartlearn-primary) !important;
    font-weight: 700;
    border-inline-start-color: var(--smartlearn-primary);
}

@media (prefers-reduced-motion: reduce) {
    .sl-article-chapters { scroll-behavior: auto; }
    .sl-article-chapters .sl-toc-link,
    .sl-article-chapters .sl-toc-chevron { transition: none; }
}

