(function() {
    function init() {
        var sections = document.querySelectorAll('.sl-article-chapters');
        sections.forEach(function(section, idx) {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';

            var uid = 'sl-chap-' + idx + '-' + Math.random().toString(36).slice(2, 7);
            var chapters = section.querySelectorAll('.sl-chapter');
            var tocLinks = section.querySelectorAll('.sl-toc-link');
            var mobileToggle = section.querySelector('.sl-mobile-toc-toggle');
            var mobileCollapse = section.querySelector('.sl-mobile-toc-collapse');

            if (mobileToggle && mobileCollapse) {
                var collapseId = uid + '-mobile-toc';
                mobileCollapse.id = collapseId;
                mobileToggle.setAttribute('aria-controls', collapseId);
                mobileToggle.addEventListener('click', function() {
                    var isOpen = mobileCollapse.classList.toggle('show');
                    mobileToggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
                });
            }

            if (chapters.length === 0 || tocLinks.length === 0) return;

            chapters.forEach(function(ch) {
                var key = ch.getAttribute('data-chapter');
                if (key) ch.id = uid + '-' + key;
            });

            function setActiveChapter(key) {
                tocLinks.forEach(function(link) {
                    var isMatch = link.getAttribute('data-target') === key;
                    link.classList.toggle('active', isMatch);
                    if (isMatch) {
                        link.setAttribute('aria-current', 'location');
                    } else {
                        link.removeAttribute('aria-current');
                    }
                });
            }

            if ('IntersectionObserver' in window) {
                var observer = new IntersectionObserver(function(entries) {
                    entries.forEach(function(entry) {
                        if (entry.isIntersecting) {
                            var key = entry.target.getAttribute('data-chapter');
                            if (key) setActiveChapter(key);
                        }
                    });
                }, { root: null, rootMargin: '-20% 0px -65% 0px', threshold: 0 });

                chapters.forEach(function(ch) { observer.observe(ch); });
            }

            var scrollTick = false;
            window.addEventListener('scroll', function() {
                if (scrollTick) return;
                scrollTick = true;
                requestAnimationFrame(function() {
                    scrollTick = false;
                    var last = chapters[chapters.length - 1];
                    if (!last) return;
                    var rect = section.getBoundingClientRect();
                    if (rect.bottom <= window.innerHeight + 40 && rect.bottom > 0) {
                        var key = last.getAttribute('data-chapter');
                        if (key) setActiveChapter(key);
                    }
                });
            }, { passive: true });

            var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
            tocLinks.forEach(function(link) {
                link.addEventListener('click', function(e) {
                    e.preventDefault();
                    var targetKey = link.getAttribute('data-target');
                    var targetEl = section.querySelector('.sl-chapter[data-chapter="' + targetKey + '"]');
                    if (targetEl) {
                        targetEl.scrollIntoView({ behavior: prefersReduced ? 'auto' : 'smooth', block: 'start' });
                        targetEl.setAttribute('tabindex', '-1');
                        targetEl.focus({ preventScroll: true });
                        setActiveChapter(targetKey);
                        if (mobileCollapse && mobileToggle && mobileCollapse.classList.contains('show')) {
                            mobileCollapse.classList.remove('show');
                            mobileToggle.setAttribute('aria-expanded', 'false');
                        }
                    }
                });
            });
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
